# ---------- TRYB TESTOWY ----------
# Pokazuje nad kazdym etapem krzykliwy przycisk "ZALICZ", zeby dalo sie
# przeklikac aplikacje bez grania. PRZED WRECZENIEM PREZENTU USTAW False.
TRYB_TESTOWY = False


def _wymagane_przed(kat):
    """Etapy wszystkich POPRZEDNICH leveli - trzeba je zaliczyc, zeby wejsc."""
    idx = KATEGORIE.index(kat)
    return [k for poprzednia in KATEGORIE[:idx] for k in poprzednia["etapy"]]


def _zablokowany_bez_testu(kat):
    return any(k not in st.session_state.rozwiazane for k in _wymagane_przed(kat))


def przygody_odblokowane():
    return not _zablokowany_bez_testu(KATEGORIE[-1])


def _postep_odblokowania(kat):
    wymagane = _wymagane_przed(kat)
    return sum(1 for k in wymagane if k in st.session_state.rozwiazane), len(wymagane)


def _kategoria_etapu(klucz):
    return next((kat for kat in KATEGORIE if klucz in kat["etapy"]), None)


def _dostep_zablokowany(kat):
    # Level N otwiera sie dopiero, gdy wszystkie poprzednie sa zaliczone
    if not kat or st.session_state.get("test_obejscie"):
        return False
    return _zablokowany_bez_testu(kat)

def etapy_kategorii(kat):
    """Etapy danej kategorii, w kolejności z definicji."""
    wg_klucza = {e["klucz"]: e for e in ETAPY}
    return [wg_klucza[k] for k in kat["etapy"] if k in wg_klucza]


# Plik stanu jest PER URZADZENIE. Wcześniej był jeden wspólny plik, więc
# dwie osoby wchodzące na tę samą stronę widziały i nadpisywały nawzajem
# swój postęp — przy prezencie to poważny problem.
KATALOG_STANOW = "stany"
DOMYSLNY_PLIK_STANU = "stan_gry.json"   # zgodność ze starym, wspólnym zapisem


def identyfikator_urzadzenia():
    """Losowy, trwały identyfikator zapisany w adresie strony."""
    iden = st.query_params.get("u")
    if iden and iden.isalnum() and 6 <= len(iden) <= 24:
        return iden
    iden = uuid.uuid4().hex[:12]
    st.query_params["u"] = iden
    return iden


def sciezka_stanu():
    iden = identyfikator_urzadzenia()
    try:
        os.makedirs(KATALOG_STANOW, exist_ok=True)
    except Exception:
        return DOMYSLNY_PLIK_STANU
    return os.path.join(KATALOG_STANOW, f"stan_{iden}.json")

