@st.cache_data(ttl=300)  # 5 minut - dość świeżo, a nie odpytuje API bez przerwy
def pobierz_dzisiejszy_wordle():
    """Próbuje pobrać dzisiejsze słowo z (angielskiego) NYT Wordle.
    Najpierw oficjalne, szeroko używane API NYT; jeśli zawiedzie, zapasowe
    API wordlehints.co.uk. Zwraca None, jeśli oba się nie powiodą —
    wtedy renderuj_wordle() spada na ręczny kod z configu."""
    # Wordle zmienia slowo o POLSKIEJ polnocy, a serwer Streamlita dziala
    # w UTC - bez tego miedzy 0:00 a 2:00 sprawdzalibysmy wczorajsze slowo.
    try:
        from zoneinfo import ZoneInfo
        from datetime import datetime
        dzis_str = datetime.now(ZoneInfo("Europe/Warsaw")).strftime("%Y-%m-%d")
    except Exception:
        dzis_str = date.today().strftime("%Y-%m-%d")

    try:
        url = f"https://www.nytimes.com/svc/wordle/v2/{dzis_str}.json"
        r = requests.get(url, timeout=5, headers={"User-Agent": "Mozilla/5.0"})
        if r.ok:
            slowo = str(r.json().get("solution", "")).strip().lower()
            if slowo:
                return slowo
    except Exception:
        pass

    try:
        r = requests.get(
            "https://wordlehints.co.uk/wp-json/wordlehint/v1/answers",
            params={"from": dzis_str, "to": dzis_str},
            timeout=5,
        )
        if r.ok:
            wyniki = r.json().get("results", [])
            if wyniki:
                slowo = str(wyniki[0].get("answer", "")).strip().lower()
                if slowo:
                    return slowo
    except Exception:
        pass

    return None


def renderuj_wordle(etap_dane):
    klucz = etap_dane["klucz"]
    st.markdown(
        "<a href='https://www.nytimes.com/games/wordle/index.html' target='_blank' "
        "style='display:block; text-align:center; text-decoration:none; "
        "background:linear-gradient(135deg,#e6c15c,#d4af37); color:#16130a; "
        "padding:0.6rem 1.4rem; border-radius:30px; font-weight:700; "
        "letter-spacing:0.01em; box-shadow:0 3px 10px rgba(0,0,0,0.35); "
        "margin-bottom:1rem;'>📝 Otwórz dzisiejsze Wordle</a>",
        unsafe_allow_html=True,
    )

    dzisiejsze_slowo = pobierz_dzisiejszy_wordle()
    if dzisiejsze_slowo is None:
        st.warning(t("wordle_brak_polaczenia"))
        if st.button(t("wordle_sprobuj_pobrac"), key=f"odswiez_{klucz}"):
            pobierz_dzisiejszy_wordle.clear()
            st.rerun()

    wpisane = st.text_input(t("twoja_odpowiedz"), key=f"pole_{klucz}")
    if st.button(t("sprawdz"), key=f"btn_{klucz}"):
        cel = dzisiejsze_slowo
        if not cel:
            zapasowa = str(etap_dane.get("odpowiedz", "")).strip().lower()
            if zapasowa and zapasowa not in ("uzupełnij", "uzupelnij"):
                cel = zapasowa
        if not cel:
            # Nie da sie sprawdzic slowa (brak polaczenia z NYT). Zamiast
            # blokowac caly prezent, ufamy: kazde 5-literowe slowo przechodzi.
            slowo = wpisane.strip().lower()
            if len(slowo) == 5 and slowo.isalpha():
                return True
            st.error(tt({"pl": "Wpisz 5-literowe słowo, które wyszło Ci w Wordle.",
                         "en": "Type the 5-letter word you got in Wordle."}))
            return None
        if wpisane.strip().lower() == cel:
            return True
        st.error(t("zle_sprobuj"))
        return False
    return None


def renderuj_data(etap_dane):
    klucz = etap_dane["klucz"]

    # Samo pytanie — inaczej nie wiadomo, jaką datę wpisać.
    if etap_dane.get("tresc"):
        st.markdown(tt(etap_dane["tresc"]))

    placeholder = t("wybierz")
    kol1, kol2, kol3 = st.columns(3)
    with kol1:
        dzien = st.selectbox(t("dzien"), [placeholder] + list(range(1, 32)), key=f"dzien_{klucz}")
    with kol2:
        miesiac = st.selectbox(t("miesiac"), [placeholder] + list(range(1, 13)), key=f"miesiac_{klucz}")
    with kol3:
        rok = st.selectbox(t("rok"), [placeholder] + list(range(2020, 2028)), key=f"rok_{klucz}")

    if st.button(t("zatwierdz"), key=f"btn_{klucz}"):
        if dzien == placeholder or miesiac == placeholder or rok == placeholder:
            st.warning(t("wybierz_najpierw"))
            return None
        try:
            wybrana = date(int(rok), int(miesiac), int(dzien))
        except ValueError:
            st.error(tt({"pl": "Taka data nie istnieje. Spróbuj jeszcze raz.", "en": "That date doesn't exist. Try again."}))
            return None
        if wybrana == etap_dane["data"]:
            return True
        st.error(tt({"pl": "To nie ta data. Spróbuj jeszcze raz 🙂", "en": "Not that date. Try again 🙂"}))
        return False
    return None


FIGURY_SYMBOLE = {
    "K": "♔", "Q": "♕", "R": "♖", "B": "♗", "N": "♘", "P": "♙",
    "k": "♚", "q": "♛", "r": "♜", "b": "♝", "n": "♞", "p": "♟",
}


def narysuj_szachownice(figury):
    komorki_html = []
    for rank in range(8, 0, -1):
        for i, plik in enumerate("abcdefgh"):
            pole = f"{plik}{rank}"
            jasne = (i + rank) % 2 == 0
            klasa = "szach-jasne" if jasne else "szach-ciemne"
            figura = figury.get(pole, "")
            symbol = FIGURY_SYMBOLE.get(figura, "")
            biala = figura.isupper()
            styl = (
                "color:#f7f1de; text-shadow:0 0 2px #000,0 0 5px rgba(0,0,0,0.8);"
                if biala else
                "color:#241505; text-shadow:0 1px 0 rgba(255,255,255,0.25);"
            )
            komorki_html.append(
                f"<div class='szach-pole {klasa}' style='{styl}'>{symbol}</div>"
            )
    st.markdown(
        f"<div class='szachownica'>{''.join(komorki_html)}</div>",
        unsafe_allow_html=True,
    )


def renderuj_szachy(etap_dane):
    klucz = etap_dane["klucz"]

    # Polecenie zadania (co właściwie trzeba znaleźć) — bez niego etap
    # jest nie do rozwiązania.
    if etap_dane.get("tresc"):
        st.markdown(tt(etap_dane["tresc"]))

    narysuj_szachownice(etap_dane["figury"])
    if etap_dane.get("format_info"):
        st.caption(tt(etap_dane["format_info"]))
    wpisane = st.text_input(t("twoj_ruch"), key=f"pole_{klucz}", label_visibility="collapsed")
    if st.button(t("sprawdz"), key=f"btn_{klucz}"):
        oczyszczony = wpisane.replace(",", " ").replace("+", "").replace("#", "")
        ruchy = [znormalizuj(tok) for tok in oczyszczony.split()]
        if ruchy == etap_dane["odpowiedz"]:
            return True
        st.error(t("zle_sprobuj"))
        return False
    return None


